// scripts/ios/command-strings.ts
import { execSync } from 'node:child_process';

export function run(udid: string, port: number): void {
  execSync(`xcrun simctl boot ${udid}`);
  execSync(`maestro --device ${udid} --driver-host-port ${port} test .maestro/flows/smoke.yaml`);
  execSync(`eas build:run -p ios --latest --simulator ${udid}`);
  execSync('eas build:run -p android --latest');
  execSync('maestro --version');
}

